304	                event = "CLAIM_PENDING";
305	            } else {
306	                claim.setSettledDue(fixed);
307	                tail = " due=" + (fixed == null ? "n/a" : fixed.toPlainString());
308	            }
309	        }
310	        claim.setStatus(next);
311	        logStatus(by, sheetId, person, claim);
312	        Claim saved = claims.saveAndFlush(claim);
313	        audit.recordOnCommit(record(event, by, person, saved) + tail);
314	        if (next == ClaimStatus.SETTLED) {
315	            watches.notifyWatchers(by, sheetId, person, saved.getNumber());
316	        }
317	        rollup.recordChanges(by, sheetId, before);
318	        return saved;
319	    }
