737	     * Previews the grade's rate at the percent on every date, saving nothing: the OPEN and PENDING claims whose
738	     * person has the grade in force on the claim's date and whose due would differ, and the sum of new due minus
739	     * current due (an n/a due counts as 0.00). A claim bound by a statement does not change.
740	     */
741	    @Transactional(readOnly = true)
742	    public RatePreview previewRate(String sheetId, String grade, BigDecimal pct) {
743	        Sheet sheet = sheets.load(sheetId);
744	        int count = 0;
745	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
746	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
747	            if (!claim.getStatus().isOpen() || claim.getSettledDue() != null || claim.isBound()) {
748	                continue;
749	            }
750	            Person person = person(sheetId, claim.getPersonId());
751	            if (!grade.equals(person.gradeOn(claim.getDate()))) {
752	                continue;
753	            }
754	            BigDecimal current = due(sheetId, person, claim);
755	            BigDecimal figure = dueOn(claim.getAmount(), pct, sheet.roundingOn(claim.getRoundsOn()));
756	            BigDecimal next = liveDue(figure, claim, person, sheet, true);
757	            BigDecimal before = current == null ? BigDecimal.ZERO : current;
758	            if (current == null || before.compareTo(next) != 0) {
759	                count++;
760	                diff = diff.add(next.subtract(before));
761	            }
762	        }
763	        return new RatePreview(count, diff.setScale(2));
764	    }
