800	    /**
801	     * The figure (null for n/a) of the claim, with a late charge added for every full 30 days it is overdue (past its
802	     * late-from: its due-by plus its grace) by the sheet's today: for each such boundary (its late-from plus 30, 60,
803	     * 90 ... days), the sheet's late
804	     * percent in force on that boundary date of the figure plus the charges of the boundaries before it (it
805	     * compounds), rounded like its due; a boundary whose percent is 0.00 adds nothing. A deferred claim is not overdue. The charge is never bound by a statement: it keeps following the
806	     * sheet's today and its policy date.
807	     */
808	    public static BigDecimal withLateCharge(BigDecimal figure, Claim claim, Person person, Sheet sheet) {
809	        if (figure == null || sheet == null || sheet.getToday() == null || claim.isDeferredOn(sheet.getToday())) {
810	            return figure;
811	        }
812	        LocalDate lateFrom = lateFrom(claim, person, sheet);
813	        long overdue = ChronoUnit.DAYS.between(lateFrom, sheet.getToday());
814	        long periods = overdue > 0 ? overdue / 30 : 0;
815	        RoundingMode rounding = sheet.roundingOn(claim.getRoundsOn());
816	        BigDecimal due = figure;
817	        for (long k = 1; k <= periods; k++) {
818	            BigDecimal latePct = sheet.latePctOn(lateFrom.plusDays(30 * k));
819	            if (latePct.signum() != 0) {
820	                due = due.add(dueOn(due, latePct, rounding));
821	            }
822	        }
823	        return due;
824	    }
