452	/**
453	 * Keeps every state each sheet stands in, and answers for a sheet as it stood at the end of a day.
454	 *
455	 * After each change to a sheet, every row kept for it is stored, with the sheet's today then (see
456	 * {@link #capture}). The rows kept for a sheet are found from the schema itself: those of the sheet, of each table
457	 * with a sheet_id, and of each table that refers to rows so kept; so a table added later is kept with no more ado.
458	 *
459	 * A sheet as of a day is a store of its own (see {@link #storeAsOf}): the schema, holding the last state stored
460	 * while the sheet's today was on or before the day (an empty sheet when there is none), with the day as its today.
461	 * The whole app reads it unchanged, so every figure on the screen is as of the day.
462	 */
463	@Service
464	public class AsOfService {
465	    /** The tables that keep no sheet's data. */
466	    private static final Set<String> NOT_KEPT = Set.of("FLYWAY_SCHEMA_HISTORY", "SHEET_SNAPSHOT");
467	    /** How many stores as of a day are kept at once, each for a sheet's state and a day. */
468	    private static final int STORES_KEPT = 32;
469	    /** A table whose rows are kept for a sheet: the stored columns, and the rows' filter by the sheet's id. */
470	    private record Kept(String table, List<String> columns, String where) {
471	    }
472	    /** A store as of a day, kept alive by its open connection. */
473	    private record Store(DataSource dataSource, Connection holder) {
474	    }
475	    private final DataSource dataSource;
476	    private final JdbcTemplate jdbc;
477	    private final SheetSnapshotRepository snapshots;
478	    private final AtomicLong storeNames = new AtomicLong();
479	    private final Map<String, Store> stores = new LinkedHashMap<>(16, 0.75f, true);
480	    private volatile List<Kept> kept;
481	    private volatile List<String> schema;
482	    public AsOfService(DataSource dataSource, SheetSnapshotRepository snapshots) {
483	        this.dataSource = dataSource;
484	        this.jdbc = new JdbcTemplate(dataSource);
485	        this.snapshots = snapshots;
486	    }
487	    /** Stores the sheet's state as it stands now, with its today, unless it is the state last stored. */
488	    @Transactional(isolation = Isolation.REPEATABLE_READ)
489	    public void capture(String sheetId) {
490	        List<LocalDate> today = jdbc.queryForList("SELECT today FROM sheet WHERE id = ?", LocalDate.class, sheetId);
491	        if (today.isEmpty()) {
492	            return;
493	        }
494	        List<SheetState.Table> tables = new ArrayList<>();
495	        for (Kept k : kept()) {
496	            String columns = k.columns().stream().map(AsOfService::quoted).collect(Collectors.joining(", "));
497	            String order = IntStream.rangeClosed(1, k.columns().size()).mapToObj(Integer::toString)
498	                    .collect(Collectors.joining(", "));
499	            List<Object[]> rows = jdbc.query(
500	                    "SELECT " + columns + " FROM " + quoted(k.table()) + " WHERE " + k.where() + " ORDER BY " + order,
501	                    (rs, n) -> {
502	                        Object[] row = new Object[k.columns().size()];
503	                        for (int i = 0; i < row.length; i++) {
504	                            row[i] = rs.getObject(i + 1);
505	                        }
506	                        return row;
507	                    }, sheetId);
508	            tables.add(new SheetState.Table(k.table(), k.columns(), rows));
509	        }
510	        byte[] data = new SheetState(tables).toBytes();
511	        String digest = SheetState.digest(data);
512	        if (snapshots.latestDigests(sheetId, Limit.of(1)).contains(digest)) {
513	            return;
514	        }
515	        snapshots.saveAndFlush(new SheetSnapshot(sheetId, today.get(0), digest, data));
516	    }
517	    /**
518	     * The store holding the sheet as it stood at the end of the day: the last state stored while its today was on or
519	     * before the day (an empty sheet with none), with the day standing in for its today. Only to be read.
520	     */
521	    @Transactional(readOnly = true)
522	    public DataSource storeAsOf(String sheetId, LocalDate day) {
523	        List<Long> ids = snapshots.idsMadeBy(sheetId, day, Limit.of(1));
524	        Long id = ids.isEmpty() ? null : ids.get(0);
525	        String key = sheetId + "|" + id + "|" + day;
526	        synchronized (stores) {
527	            Store store = stores.get(key);
528	            if (store == null) {
529	                SheetState state = id == null ? null : SheetState.of(snapshots.findById(id).orElseThrow().getData());
530	                store = open(sheetId, day, state);
531	                stores.put(key, store);
532	                if (stores.size() > STORES_KEPT) {
533	                    String eldest = stores.keySet().iterator().next();
534	                    close(stores.remove(eldest));
535	                }
536	            }
537	            return store.dataSource();
538	        }
539	    }
540	    /** Opens a store of its own with the schema, the state's rows and the day as the sheet's today. */
541	    private Store open(String sheetId, LocalDate day, SheetState state) {
542	        String url = "jdbc:h2:mem:asof-" + storeNames.incrementAndGet();
543	        try {
544	            Connection holder = DriverManager.getConnection(url, "sa", "");
545	            try (Statement st = holder.createStatement()) {
546	                for (String sql : schema()) {
547	                    st.execute(sql);
548	                }
549	                // the store closes once its last connection does
550	                st.execute("SET DB_CLOSE_DELAY 0");
551	                // the rows are as they stood together, in whatever order; they are read, never changed
552	                st.execute("SET REFERENTIAL_INTEGRITY FALSE");
553	            }
554	            if (state != null) {
555	                for (SheetState.Table t : state.tables()) {
556	                    if (t.rows().isEmpty()) {
557	                        continue;
558	                    }
559	                    String sql = "INSERT INTO " + quoted(t.name()) + " ("
560	                            + t.columns().stream().map(AsOfService::quoted).collect(Collectors.joining(", "))
561	                            + ") VALUES (" + t.columns().stream().map(c -> "?").collect(Collectors.joining(", ")) + ")";
562	                    try (PreparedStatement insert = holder.prepareStatement(sql)) {
563	                        for (Object[] row : t.rows()) {
564	                            for (int i = 0; i < row.length; i++) {
565	                                insert.setObject(i + 1, row[i]);
566	                            }
567	                            insert.addBatch();
568	                        }
569	                        insert.executeBatch();
570	                    }
571	                }
572	            }
573	            try (PreparedStatement today = holder.prepareStatement("UPDATE sheet SET today = ? WHERE id = ?")) {
574	                today.setObject(1, day);
575	                today.setString(2, sheetId);
576	                if (today.executeUpdate() == 0) {
577	                    try (PreparedStatement empty = holder.prepareStatement(
578	                            "INSERT INTO sheet (id, created_at, today) VALUES (?, CURRENT_TIMESTAMP, ?)")) {
579	                        empty.setString(1, sheetId);
580	                        empty.setObject(2, day);
581	                        empty.executeUpdate();
582	                    }
583	                }
584	            }
585	            return new Store(new DriverManagerDataSource(url + ";IFEXISTS=TRUE", "sa", ""), holder);
586	        } catch (SQLException e) {
587	            throw new IllegalStateException("Could not open the sheet as of " + day, e);
588	        }
589	    }
590	    private static void close(Store store) {
591	        try {
592	            store.holder().close();
593	        } catch (SQLException e) {
594	            // already gone
595	        }
596	    }
597	    /** The schema, as statements that create it empty. */
598	    private List<String> schema() {
599	        List<String> s = schema;
600	        if (s == null) {
601	            s = List.copyOf(jdbc.queryForList("SCRIPT NODATA", String.class));
602	            schema = s;
603	        }
604	        return s;
605	    }
606	    /** The tables whose rows are kept for a sheet, found from the schema. */
607	    private List<Kept> kept() {
608	        List<Kept> k = kept;
609	        if (k == null) {
610	            k = jdbc.execute(AsOfService::findKept);
611	            kept = k;
612	        }
613	        return k;
614	    }
615	    private static List<Kept> findKept(Connection c) throws SQLException {
616	        Map<String, List<String>> columns = new LinkedHashMap<>();
617	        Map<String, Boolean> hasSheetId = new LinkedHashMap<>();
618	        try (PreparedStatement q = c.prepareStatement(
619	                "SELECT c.TABLE_NAME, c.COLUMN_NAME, c.IS_GENERATED FROM INFORMATION_SCHEMA.COLUMNS c"
620	                        + " JOIN INFORMATION_SCHEMA.TABLES t ON t.TABLE_SCHEMA = c.TABLE_SCHEMA"
621	                        + " AND t.TABLE_NAME = c.TABLE_NAME"
622	                        + " WHERE c.TABLE_SCHEMA = 'PUBLIC' AND t.TABLE_TYPE = 'BASE TABLE'"
623	                        + " ORDER BY c.TABLE_NAME, c.ORDINAL_POSITION");
624	                ResultSet rs = q.executeQuery()) {
625	            while (rs.next()) {
626	                String table = rs.getString(1);
627	                if (NOT_KEPT.contains(table)) {
628	                    continue;
629	                }
630	                columns.computeIfAbsent(table, t -> new ArrayList<>());
631	                if ("SHEET_ID".equals(rs.getString(2))) {
632	                    hasSheetId.put(table, true);
633	                }
634	                if (!"ALWAYS".equals(rs.getString(3))) {
635	                    columns.get(table).add(rs.getString(2));
636	                }
637	            }
638	        }
639	        Map<String, String> where = new LinkedHashMap<>();
640	        for (String table : columns.keySet()) {
641	            if (table.equals("SHEET")) {
642	                where.put(table, quoted("ID") + " = ?");
643	            } else if (hasSheetId.getOrDefault(table, false)) {
644	                where.put(table, quoted("SHEET_ID") + " = ?");
645	            }
646	        }
647	        // a table with no sheet_id is kept through a row it refers to that is kept
648	        DatabaseMetaData meta = c.getMetaData();
649	        boolean found = true;
650	        while (found) {
651	            found = false;
652	            for (String table : columns.keySet()) {
653	                if (where.containsKey(table)) {
654	                    continue;
655	                }
656	                try (ResultSet keys = meta.getImportedKeys(null, "PUBLIC", table)) {
657	                    while (keys.next()) {
658	                        String parent = keys.getString("PKTABLE_NAME");
659	                        if (where.containsKey(parent)) {
660	                            where.put(table, quoted(keys.getString("FKCOLUMN_NAME")) + " IN (SELECT "
661	                                    + quoted(keys.getString("PKCOLUMN_NAME")) + " FROM " + quoted(parent) + " WHERE "
662	                                    + where.get(parent) + ")");
663	                            found = true;
664	                            break;
665	                        }
666	                    }
667	                }
668	            }
669	        }
670	        List<Kept> kept = new ArrayList<>();
671	        where.forEach((table, w) -> kept.add(new Kept(table, List.copyOf(columns.get(table)), w)));
672	        return List.copyOf(kept);
673	    }
674	    private static String quoted(String name) {
675	        return '"' + name.replace("\"", "\"\"") + '"';
676	    }
