        String note = f.length > 3 ? f[3].strip() : "";
        String ref = null;
        int hash = note.lastIndexOf(" #");
        if (hash >= 0) {
            ref = note.substring(hash + 2).strip();
            note = note.substring(0, hash).strip();
        }
